/**
 * Product icon artwork, copied from the desktop client's icon set
 * (`packages/client/ui-primitives/src/icons/artwork.ts`).
 *
 * The glyphs are the desktop client's own drawings, so a control that exists on
 * both clients shows the same shape. Each entry is the SVG the desktop renders
 * at one stroke weight; the mobile client substitutes its colour for
 * `currentColor` and keeps the geometry untouched.
 *
 * Copied rather than depended on: the desktop package belongs to the
 * deepseek-harness workspace and is not published to this app.
 */

/** Stroke width of the regular weight. */
export const ICON_REGULAR_STROKE = 1

/** Stroke width of the medium weight, used for emphasised controls. */
export const ICON_MEDIUM_STROKE = 1.3

/** One glyph: its default height, box ratio when not square, and SVG per weight. */
export interface IconArtwork {
  size: number
  aspect?: readonly [number, number]
  svg: (strokeWidth: number) => string
}

